'use client'

import '@xterm/xterm/css/xterm.css'

import { LoaderCircleIcon, RotateCwIcon, TriangleAlertIcon, XIcon } from 'lucide-react'
import * as React from 'react'

import { Button } from '@/components/ui/button'
import type {
  FxColorScheme,
  FxGatewayRefusal,
  FxTerminalSession,
} from '@/components/ui/fx-terminal/runtime'
import type { FxExecEvent } from '@/components/ui/fx-terminal/workspace'
import { type StatusTone, statusInkClasses } from '@/components/ui/token-status'
import {
  type AgentNotice,
  type AgentNoticeTone,
  type AgentUnavailableReason,
  describeAgentUnavailableReason,
} from '@/lib/agent-types'
import { cn } from '@/lib/utils'
import type { ViewerAgentTools } from '@/lib/viewer-agent-tools'

interface FxTerminalHandle {
  focus(): void
  fit(): void
}

interface FxTerminalProps {
  tools: ViewerAgentTools
  /** Same-origin proxy that holds the AI Gateway key. */
  gatewayBase?: string
  model?: string
  effort?: string
  /** Omit to follow the `.dark` class on the document, live. */
  colorScheme?: FxColorScheme
  onExec?: (event: FxExecEvent) => void
  onReady?: () => void
  className?: string
  ref?: React.Ref<FxTerminalHandle>
}

type FxTerminalStatus =
  | { kind: 'starting' }
  | { kind: 'ready' }
  | { kind: 'unsupported' }
  | { kind: 'error'; title: string; message: string }

const noticeTone = {
  neutral: 'neutral',
  warning: 'warning',
  danger: 'danger',
} satisfies Record<AgentNoticeTone, StatusTone>

const noticeSurface = {
  neutral: 'bg-status-neutral-surface',
  warning: 'bg-status-warning-surface',
  danger: 'bg-status-danger-surface',
} satisfies Record<AgentNoticeTone, string>

const refusalReasons = new Map<string, AgentUnavailableReason>([
  ['not-configured', 'not-configured'],
  ['rate-limited', 'rate-limited'],
  ['model-not-allowed', 'model-not-allowed'],
])

function describeRefusal(refusal: FxGatewayRefusal): AgentNotice {
  const reason = refusalReasons.get(refusal.type)
  if (reason) return describeAgentUnavailableReason(reason)
  return {
    title: 'The model proxy refused the request',
    description: refusal.message,
    tone: refusal.status === 413 ? 'warning' : 'danger',
  }
}

function subscribeToDocumentScheme(onChange: () => void): () => void {
  const observer = new MutationObserver(onChange)
  observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] })
  return () => observer.disconnect()
}

function documentScheme(): FxColorScheme {
  return document.documentElement.classList.contains('dark') ? 'dark' : 'light'
}

function serverScheme(): FxColorScheme {
  return 'light'
}

function FxTerminal({
  tools,
  gatewayBase = '/api/agent/gateway',
  model = 'anthropic/claude-haiku-5.5',
  effort = 'low',
  colorScheme,
  onExec,
  onReady,
  className,
  ref,
}: FxTerminalProps) {
  const followed = React.useSyncExternalStore(
    subscribeToDocumentScheme,
    documentScheme,
    serverScheme,
  )
  const scheme = colorScheme ?? followed
  const initialScheme = React.useEffectEvent(() => scheme)
  const handleExec = React.useEffectEvent((event: FxExecEvent) => onExec?.(event))
  const handleReady = React.useEffectEvent(() => onReady?.())

  const [container, setContainer] = React.useState<HTMLDivElement | null>(null)
  const [session, setSession] = React.useState<FxTerminalSession | null>(null)
  const [status, setStatus] = React.useState<FxTerminalStatus>({ kind: 'starting' })
  const [refusal, setRefusal] = React.useState<FxGatewayRefusal | null>(null)
  const [attempt, setAttempt] = React.useState(0)

  React.useImperativeHandle(
    ref,
    () => ({ focus: () => session?.focus(), fit: () => session?.fit() }),
    [session],
  )

  React.useEffect(() => {
    if (!container) return
    const aborter = new AbortController()
    let current: FxTerminalSession | null = null
    void (async () => {
      try {
        const { supportsJspi } = await import('libfx/browser')
        if (aborter.signal.aborted) return
        if (!supportsJspi()) {
          setStatus({ kind: 'unsupported' })
          return
        }
        const { startFxTerminal } = await import('@/components/ui/fx-terminal/runtime')
        const started = await startFxTerminal(container, {
          tools,
          gatewayBase,
          model,
          effort,
          colorScheme: initialScheme(),
          signal: aborter.signal,
          onExec: handleExec,
          onRefusal: setRefusal,
        })
        if (aborter.signal.aborted) {
          started.dispose()
          return
        }
        current = started
        setSession(started)
        setStatus({ kind: 'ready' })
        handleReady()
        void started.exited.then((code) => {
          if (aborter.signal.aborted) return
          setSession(null)
          setStatus({
            kind: 'error',
            title: 'The agent stopped',
            message: `fx exited with code ${code}. Retry starts a new session.`,
          })
        })
      } catch (error) {
        if (aborter.signal.aborted) return
        setStatus({
          kind: 'error',
          title: "The agent couldn't start",
          message:
            error instanceof TypeError
              ? 'The agent runtime could not be downloaded. Check the connection and retry.'
              : error instanceof Error
                ? error.message
                : 'The terminal failed to start.',
        })
      }
    })()
    return () => {
      aborter.abort()
      current?.dispose()
      setSession(null)
    }
  }, [container, tools, gatewayBase, model, effort])

  const retry = () => {
    setStatus({ kind: 'starting' })
    setRefusal(null)
    setAttempt((count) => count + 1)
  }

  React.useEffect(() => {
    session?.setColorScheme(scheme)
  }, [session, scheme])

  React.useEffect(() => {
    if (!session) return
    const frame = requestAnimationFrame(() => {
      session.fit()
      session.focus()
    })
    return () => cancelAnimationFrame(frame)
  }, [session])

  const banner = refusal ? describeRefusal(refusal) : null
  const background = scheme === 'dark' ? '#0a0a0a' : '#fafafa'

  return (
    <section
      data-slot="fx-terminal"
      aria-label="fx terminal"
      className={cn('flex min-h-0 flex-col bg-background text-foreground', className)}
    >
      {banner && (
        <div
          role="alert"
          className={cn(
            'flex shrink-0 items-start gap-3 border-border border-b px-4 py-3',
            noticeSurface[banner.tone],
          )}
        >
          <TriangleAlertIcon
            aria-hidden
            className={cn('mt-0.5 size-4 shrink-0', statusInkClasses[noticeTone[banner.tone]])}
          />
          <div className="flex min-w-0 flex-1 flex-col gap-0.5">
            <p className="font-medium text-sm">{banner.title}</p>
            <p className="text-muted-foreground text-xs">{banner.description}</p>
          </div>
          <Button
            variant="ghost"
            size="icon"
            className="-my-2 size-11"
            aria-label="Dismiss"
            onClick={() => setRefusal(null)}
          >
            <XIcon aria-hidden />
          </Button>
        </div>
      )}

      <div className="relative flex min-h-0 flex-1 flex-col p-3 dark:p-0">
        <div
          className={cn(
            'flex min-h-0 flex-1 flex-col rounded-lg py-3 ps-3.5 dark:rounded-none dark:py-2 dark:ps-4',
            scheme === 'light' && 'border border-border dark:border-0',
            status.kind !== 'ready' && 'invisible',
          )}
          style={{ background }}
          aria-hidden={status.kind !== 'ready'}
        >
          <div key={attempt} ref={setContainer} className="min-h-0 flex-1" />
        </div>

        {status.kind === 'starting' && (
          <div
            role="status"
            className="absolute inset-0 flex items-center justify-center gap-2 text-muted-foreground text-sm"
          >
            <span className="grid size-4 animate-spin place-items-center">
              <LoaderCircleIcon aria-hidden className="size-4" />
            </span>
            Starting the agent…
          </div>
        )}

        {status.kind === 'unsupported' && (
          <Notice notice={describeAgentUnavailableReason('unsupported-browser')} />
        )}

        {status.kind === 'error' && (
          <Notice
            notice={{
              title: status.title,
              description: status.message,
              tone: 'danger',
            }}
            action={
              <Button variant="outline" className="h-11 px-4" onClick={retry}>
                <RotateCwIcon aria-hidden />
                Retry
              </Button>
            }
          />
        )}
      </div>
    </section>
  )
}

function Notice({ notice, action }: { notice: AgentNotice; action?: React.ReactNode }) {
  return (
    <div
      role={notice.tone === 'danger' ? 'alert' : 'status'}
      className="absolute inset-0 flex flex-col items-center justify-center gap-3 px-6 text-center"
    >
      <span
        className={cn(
          'grid size-10 place-items-center rounded-full',
          noticeSurface[notice.tone],
          statusInkClasses[noticeTone[notice.tone]],
        )}
      >
        <TriangleAlertIcon aria-hidden className="size-5" />
      </span>
      <div className="flex max-w-xs flex-col gap-1">
        <p className="text-balance font-medium text-sm">{notice.title}</p>
        <p className="text-pretty text-muted-foreground text-sm">{notice.description}</p>
      </div>
      {action}
    </div>
  )
}

export type { FxColorScheme, FxExecEvent, FxGatewayRefusal }
export { FxTerminal, type FxTerminalHandle, type FxTerminalProps }

import { FitAddon } from '@xterm/addon-fit'
import { type ITheme, Terminal } from '@xterm/xterm'
import {
  type ConfigStore,
  createFxTerminal,
  type PromptHistoryStore,
  type TerminalRuntime,
  xtermAdapter,
} from 'libfx/browser'
import { createViewerWorkspace, type FxExecEvent } from '@/components/ui/fx-terminal/workspace'
import type { ViewerAgentTools } from '@/lib/viewer-agent-tools'

export type FxColorScheme = 'light' | 'dark'

export interface FxGatewayRefusal {
  status: number
  type: string
  message: string
}

export interface FxTerminalSession {
  exited: Promise<number>
  focus(): void
  fit(): void
  setColorScheme(scheme: FxColorScheme): void
  dispose(): void
}

export interface FxTerminalStartOptions {
  tools: ViewerAgentTools
  gatewayBase: string
  model: string
  effort: string
  colorScheme: FxColorScheme
  signal: AbortSignal
  onExec?: (event: FxExecEvent) => void
  onRefusal?: (refusal: FxGatewayRefusal) => void
}

const GATEWAY_ORIGIN = 'https://ai-gateway.vercel.sh'
const REFUSAL_STATUSES = new Set([400, 403, 413, 429, 503])
const INTERACTIVE_TIMEOUT_MS = 30_000
const STORAGE_PREFIX = 'cantera.fx.'
const HISTORY_LIMIT = 100

const darkTheme: ITheme = {
  background: '#0a0a0a',
  foreground: '#ededed',
  cursor: '#ededed',
  cursorAccent: '#0a0a0a',
  selectionBackground: '#404040',
  black: '#0a0a0a',
  red: '#f87171',
  green: '#4ade80',
  yellow: '#facc15',
  blue: '#60a5fa',
  magenta: '#c084fc',
  cyan: '#22d3ee',
  white: '#d4d4d4',
  brightBlack: '#737373',
  brightRed: '#fca5a5',
  brightGreen: '#86efac',
  brightYellow: '#fde047',
  brightBlue: '#93c5fd',
  brightMagenta: '#d8b4fe',
  brightCyan: '#67e8f9',
  brightWhite: '#ffffff',
}

const lightTheme: ITheme = {
  background: '#fafafa',
  foreground: '#0a0a0a',
  cursor: '#0a0a0a',
  cursorAccent: '#fafafa',
  selectionBackground: '#d4d4d4',
  black: '#171717',
  red: '#dc2626',
  green: '#15803d',
  yellow: '#a16207',
  blue: '#1d4ed8',
  magenta: '#9333ea',
  cyan: '#0e7490',
  white: '#737373',
  brightBlack: '#737373',
  brightRed: '#b91c1c',
  brightGreen: '#166534',
  brightYellow: '#854d0e',
  brightBlue: '#1e40af',
  brightMagenta: '#7e22ce',
  brightCyan: '#155e75',
  brightWhite: '#0a0a0a',
}

export function terminalBackground(scheme: FxColorScheme): string {
  return (scheme === 'dark' ? darkTheme : lightTheme).background ?? 'transparent'
}

function mirroredGreyscale(): string[] {
  const levels = [0, 95, 135, 175, 215, 255]
  const hex = (value: number) => value.toString(16).padStart(2, '0')
  const palette: string[] = []
  for (const r of levels) {
    for (const g of levels) {
      for (const b of levels) palette.push(`#${hex(r)}${hex(g)}${hex(b)}`)
    }
  }
  for (let step = 0; step < 24; step++) {
    const grey = hex(255 - (8 + 10 * step))
    palette.push(`#${grey}${grey}${grey}`)
  }
  return palette
}

// fx picks its muted greys once, for FX_THEME at start; after a live switch the
// 256-colour grey ramp is mirrored so that text stays readable.
function themeFor(scheme: FxColorScheme, startedAs: FxColorScheme): ITheme {
  const theme = scheme === 'dark' ? darkTheme : lightTheme
  return scheme === startedAs ? theme : { ...theme, extendedAnsi: mirroredGreyscale() }
}

function storage(): Storage | null {
  try {
    return globalThis.localStorage ?? null
  } catch {
    return null
  }
}

function read(key: string): string | null {
  try {
    return storage()?.getItem(STORAGE_PREFIX + key) ?? null
  } catch {
    return null
  }
}

function write(key: string, value: string | null) {
  try {
    if (value === null) storage()?.removeItem(STORAGE_PREFIX + key)
    else storage()?.setItem(STORAGE_PREFIX + key, value)
  } catch {
    return
  }
}

// A stored model would override FX_MODEL, and the proxy refuses every other model.
function createConfigStore(model: string): ConfigStore {
  return {
    get(id) {
      const value = read(`config.${id}`)
      return id === 'model' && value !== model ? null : value
    },
    set(id, value) {
      write(`config.${id}`, value)
    },
  }
}

function loadHistory(root: string): string[] {
  try {
    const parsed: unknown = JSON.parse(read(`history.${root}`) ?? '[]')
    return Array.isArray(parsed) ? parsed.filter((entry) => typeof entry === 'string') : []
  } catch {
    return []
  }
}

function createPromptHistoryStore(): PromptHistoryStore {
  return {
    load: (root, limit) => loadHistory(root).slice(-Math.max(0, limit)),
    append(root, value) {
      const entries = loadHistory(root)
      if (entries.at(-1) === value) return 'duplicate'
      write(`history.${root}`, JSON.stringify([...entries, value].slice(-HISTORY_LIMIT)))
    },
    clear: (root) => write(`history.${root}`, null),
  }
}

function localRefusal(url: string): Response {
  return Response.json(
    { error: { type: 'invalid-request', message: `Requests to ${url} are not allowed here.` } },
    { status: 403 },
  )
}

async function readRefusal(response: Response): Promise<FxGatewayRefusal | null> {
  try {
    const body: unknown = await response.clone().json()
    const error = body && typeof body === 'object' && 'error' in body ? body.error : null
    if (!error || typeof error !== 'object') return null
    const type = 'type' in error ? error.type : undefined
    const message = 'message' in error ? error.message : undefined
    if (typeof type !== 'string' || typeof message !== 'string') return null
    return { status: response.status, type, message }
  } catch {
    return null
  }
}

export function createGatewayFetch(
  gatewayBase: string,
  onRefusal?: (refusal: FxGatewayRefusal) => void,
): typeof fetch {
  const base = new URL(gatewayBase.replace(/\/$/, ''), globalThis.location?.href).href
  return async (input, init) => {
    const raw = typeof input === 'string' ? input : input instanceof URL ? input.href : input.url
    let url: URL
    try {
      url = new URL(raw)
    } catch {
      return localRefusal(raw)
    }
    if (url.origin !== GATEWAY_ORIGIN) return localRefusal(`${url.origin}${url.pathname}`)
    const target = `${base}${url.pathname}${url.search}`
    const response = await fetch(
      input instanceof Request ? new Request(target, input) : target,
      init,
    )
    if (onRefusal && REFUSAL_STATUSES.has(response.status)) {
      const refusal = await readRefusal(response)
      if (refusal) onRefusal(refusal)
    }
    return response
  }
}

function withTimeout<T>(promise: Promise<T>, ms: number, message: string): Promise<T> {
  return new Promise<T>((resolve, reject) => {
    const timer = setTimeout(() => reject(new Error(message)), ms)
    promise.then(
      (value) => {
        clearTimeout(timer)
        resolve(value)
      },
      (error: unknown) => {
        clearTimeout(timer)
        reject(error)
      },
    )
  })
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms))

// The browser terminal reads no effort from env or args, and fx cannot save
// /model to its settings file there (it prints an error), so effort is chosen
// through /model and the screen is reset with /clear before it is shown.
async function applyEffort(
  runtime: TerminalRuntime,
  options: FxTerminalStartOptions,
  saved: Promise<void>,
  clearScrollback: () => void,
) {
  runtime.write(`/model ${options.model} ${options.effort}`)
  await sleep(150)
  runtime.write('\r')
  await Promise.race([saved, sleep(3000)])
  await sleep(150)
  clearScrollback()
  runtime.write('/clear')
  await sleep(150)
  runtime.write('\r')
  await sleep(250)
}

function throwIfAborted(signal: AbortSignal) {
  if (signal.aborted) throw new Error('The terminal closed while the agent was starting.')
}

export async function startFxTerminal(
  container: HTMLElement,
  options: FxTerminalStartOptions,
): Promise<FxTerminalSession> {
  const terminal = new Terminal({
    allowProposedApi: true,
    cursorBlink: true,
    cursorStyle: 'bar',
    cursorWidth: 1,
    fontFamily: 'ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace',
    fontSize: 13,
    fontWeightBold: 600,
    lineHeight: 1.25,
    scrollback: 5000,
    scrollOnUserInput: true,
    theme: themeFor(options.colorScheme, options.colorScheme),
  })
  const fit = new FitAddon()
  terminal.loadAddon(fit)
  terminal.open(container)
  const safeFit = () => {
    try {
      if (container.clientWidth > 0 && container.clientHeight > 0) fit.fit()
    } catch {
      return
    }
  }
  safeFit()
  let frame: number | null = null
  const resizeObserver = new ResizeObserver(() => {
    if (frame !== null) return
    frame = requestAnimationFrame(() => {
      frame = null
      safeFit()
    })
  })
  resizeObserver.observe(container)

  let runtime: TerminalRuntime | null = null
  let disposed = false
  const dispose = () => {
    if (disposed) return
    disposed = true
    if (frame !== null) cancelAnimationFrame(frame)
    resizeObserver.disconnect()
    try {
      runtime?.abort()
    } catch {
      return
    } finally {
      terminal.dispose()
    }
  }

  try {
    throwIfAborted(options.signal)
    const workspace = createViewerWorkspace(options.tools, {
      gatewayBase: options.gatewayBase,
      model: options.model,
      onExec: options.onExec,
    })
    let modelSaved = () => {}
    const saved = new Promise<void>((resolve) => {
      modelSaved = resolve
    })
    runtime = await createFxTerminal({
      terminal: xtermAdapter(terminal),
      env: {
        AI_GATEWAY_API_KEY: 'proxy',
        FX_MODEL: options.model,
        FX_THEME: options.colorScheme,
      },
      onEvent: (event) => {
        if (event.type === 'config.changed' && event.configId === 'model') modelSaved()
      },
      fetch: createGatewayFetch(options.gatewayBase, options.onRefusal),
      workspace,
      configStore: createConfigStore(options.model),
      promptHistoryStore: createPromptHistoryStore(),
    })
    throwIfAborted(options.signal)
    await withTimeout(
      runtime.interactive,
      INTERACTIVE_TIMEOUT_MS,
      'The agent did not start in time. Try again.',
    )
    throwIfAborted(options.signal)
    await applyEffort(runtime, options, saved, () => terminal.clear())
    throwIfAborted(options.signal)
  } catch (error) {
    dispose()
    throw error
  }

  const started = runtime
  terminal.focus()
  return {
    exited: started.exited,
    focus: () => {
      if (!disposed) terminal.focus()
    },
    fit: () => {
      if (!disposed) safeFit()
    },
    setColorScheme: (scheme) => {
      if (!disposed) terminal.options.theme = themeFor(scheme, options.colorScheme)
    },
    dispose,
  }
}

import { Bash, type CommandContext, defineCommand } from 'just-bash/browser'
import type { WorkspaceAdapter, WorkspaceExecResult } from 'libfx/browser'

import {
  checkImage,
  describeImage,
  formatBytes,
  fromBase64,
  ImageError,
  imageExtension,
  SHOTS_DIR,
  shotFileName,
  toBase64,
} from '@/components/ui/fx-terminal/images'
import type { AgentTool, AgentToolResult, AgentToolSchemaProperty } from '@/lib/agent-types'
import type { ViewerAgentTools } from '@/lib/viewer-agent-tools'

export interface FxExecEvent {
  command: string
  exitCode: number
  ms: number
}

export interface ViewerWorkspaceOptions {
  gatewayBase: string
  model: string
  onExec?: (event: FxExecEvent) => void
  fetch?: typeof fetch
}

type WorkspaceFs = CommandContext['fs']

const ROOT = '/model'
const HOME = '/home/agent'
const OUTPUT_LIMIT_BYTES = 60 * 1024
const TOOL_BUDGET_MS = 25_000
const EXIT_STILL_RUNNING = 75
const EXIT_INTERRUPTED = 130

type ToolValue = string | number | boolean | string[] | number[]

class UsageError extends Error {}

interface Job {
  id: number
  tool: string
  controller: AbortController
  result: Promise<AgentToolResult>
  render: (result: AgentToolResult, fs: WorkspaceFs) => Promise<string>
}

const SCREENSHOT_TOOL = 'take_screenshot'
const SCREENSHOT_HELP = `Save an image of the current view under ${SHOTS_DIR}/ (shot-1.jpg, shot-2.jpg, ...). You do not see the pixels; viewer describe_image <path> returns a text description.`
const NAME_FLAG = '--name <string>'
const NAME_HELP = `File name under ${SHOTS_DIR} (default shot-N; the extension is added).`
const EXPERIMENTAL =
  'experimental: the model gets a text description, not the pixels, and each call costs one extra model request'

const encoder = new TextEncoder()

function kebab(name: string): string {
  return name.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`)
}

function camel(flag: string): string {
  return flag.replace(/-([a-z])/g, (_, letter: string) => letter.toUpperCase())
}

function flagLabel(name: string): string {
  return `--${kebab(name).replace(/(^|-)set-id$/, '$1set')}`
}

function firstSentence(text: string): string {
  const match = /^.*?[.!?](\s|$)/.exec(text)
  return (match ? match[0] : text).trim()
}

function valueHint(property: AgentToolSchemaProperty): string {
  if (property.type === 'array') return `<${property.items.type},...>`
  if (property.type === 'string' && property.enum) return `<${property.enum.join('|')}>`
  return property.type === 'boolean' ? '' : `<${property.type}>`
}

function resolveFlag(tool: AgentTool, flag: string): string | undefined {
  const properties = tool.inputSchema.properties
  const name = camel(flag)
  for (const candidate of [flag, name, `${name}Id`]) {
    if (Object.hasOwn(properties, candidate)) return candidate
  }
  return undefined
}

function coerce(
  name: string,
  property: AgentToolSchemaProperty,
  raw: string,
  lastSetId: () => string,
): ToolValue {
  const label = flagLabel(name)
  const number = (text: string) => {
    const value = Number(text)
    if (text.trim() === '' || !Number.isFinite(value)) {
      throw new UsageError(`${label} needs a number (got "${text}")`)
    }
    return value
  }
  switch (property.type) {
    case 'string':
      return raw === '@last' && /(^s|S)etId$/.test(name) ? lastSetId() : raw
    case 'number':
    case 'integer':
      return number(raw)
    case 'boolean':
      if (/^(true|1|yes)$/i.test(raw)) return true
      if (/^(false|0|no)$/i.test(raw)) return false
      throw new UsageError(`${label} is true or false (got "${raw}")`)
    case 'array': {
      const items = raw
        .split(',')
        .map((item) => item.trim())
        .filter(Boolean)
      return property.items.type === 'string' ? items : items.map(number)
    }
  }
}

export function parseToolArgs(
  tool: AgentTool,
  args: readonly string[],
  lastSetId: () => string,
): Map<string, ToolValue> {
  const properties = tool.inputSchema.properties
  const raw = new Map<string, string[]>()
  const switches = new Map<string, boolean>()
  const positional: string[] = []
  const add = (name: string, value: string) => raw.set(name, [...(raw.get(name) ?? []), value])
  for (let index = 0; index < args.length; index++) {
    const arg = args[index]
    if (arg === '--') {
      positional.push(...args.slice(index + 1))
      break
    }
    if (!arg.startsWith('--') || arg.length === 2) {
      positional.push(arg)
      continue
    }
    const equals = arg.indexOf('=')
    const flag = equals > 2 ? arg.slice(2, equals) : arg.slice(2)
    const negated = flag.startsWith('no-') ? resolveFlag(tool, flag.slice(3)) : undefined
    if (negated && properties[negated]?.type === 'boolean' && equals < 0) {
      switches.set(negated, false)
      continue
    }
    const name = resolveFlag(tool, flag)
    if (!name) {
      const allowed = Object.keys(properties).map(flagLabel).join(' ')
      throw new UsageError(`unknown flag --${flag} (flags: ${allowed || 'none'})`)
    }
    const boolean = properties[name]?.type === 'boolean'
    const next = args[index + 1]
    if (equals > 2) {
      add(name, arg.slice(equals + 1))
    } else if (boolean ? next !== undefined && /^(true|false)$/i.test(next) : next !== undefined) {
      add(name, next)
      index += 1
    } else if (boolean) {
      switches.set(name, true)
    } else {
      throw new UsageError(`${flagLabel(name)} needs a value`)
    }
  }
  placePositionals(tool, positional, add)
  const input = new Map<string, ToolValue>(switches)
  for (const [name, values] of raw) {
    const property = properties[name]
    const value = property.type === 'array' ? values.join(',') : (values.at(-1) ?? '')
    input.set(name, coerce(name, property, value, lastSetId))
  }
  return input
}

function placePositionals(
  tool: AgentTool,
  positional: readonly string[],
  add: (name: string, value: string) => void,
) {
  const properties = tool.inputSchema.properties
  const rest: string[] = []
  for (const token of positional) {
    if (token === '@last' && properties.setId) add('setId', token)
    else if (/^\d+(,\d*)*$/.test(token) && properties.ids) add('ids', token)
    else rest.push(token)
  }
  if (rest.length === 0) return
  const strings = (tool.inputSchema.required ?? []).filter(
    (name) => properties[name]?.type === 'string',
  )
  if (strings.length !== 1) {
    throw new UsageError(`unexpected argument "${rest[0]}" (see viewer ${tool.name} --help)`)
  }
  add(strings[0], rest.join(' '))
}

function toolDescription(tool: AgentTool): string {
  return tool.name === SCREENSHOT_TOOL ? SCREENSHOT_HELP : tool.description
}

function toolHelp(tool: AgentTool): string {
  const required = new Set(tool.inputSchema.required ?? [])
  const flags = Object.entries(tool.inputSchema.properties).map(([name, property]) => [
    `${flagLabel(name)} ${valueHint(property)}`,
    [property.description, required.has(name) ? 'required' : ''].filter(Boolean).join(' '),
  ])
  if (tool.name === SCREENSHOT_TOOL) flags.push([NAME_FLAG, NAME_HELP])
  const lines = [`viewer ${tool.name}${tool.mutates ? '  (changes the view; undoable)' : ''}`]
  lines.push('', toolDescription(tool), '')
  if (flags.length === 0) {
    lines.push('No flags.')
  } else {
    lines.push('Flags')
    const width = Math.max(...flags.map(([usage]) => usage.length))
    for (const [usage, notes] of flags) lines.push(`  ${usage.padEnd(width)}  ${notes}`.trimEnd())
  }
  return `${lines.join('\n')}\n`
}

